--
-- Structure de la table `materiels`
--

CREATE TABLE `materiels` (
  `id` int(11) NOT NULL,
  `name` varchar(191) NOT NULL,
  `type` varchar(191) NOT NULL,
  `brand` varchar(191) NOT NULL,
  `model` varchar(191) NOT NULL,
  `serialNumber` varchar(191) NOT NULL,
  `location` varchar(191) NOT NULL,
  `status` enum('OPERATIONAL','DOWN_AT_CLIENT','IN_WORKSHOP','ON_LOAN','REPLACED','RETIRED','MAINTENANCE_REQUIRED') NOT NULL DEFAULT 'OPERATIONAL',
  `purchaseDate` datetime(3) DEFAULT NULL,
  `lastMaintenance` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `updatedAt` datetime(3) NOT NULL,
  `client` varchar(191) DEFAULT NULL,
  `code` varchar(191) DEFAULT NULL,
  `criticality` enum('LOW','MEDIUM','HIGH','CRITICAL') NOT NULL DEFAULT 'LOW',
  `service` varchar(191) DEFAULT NULL,
  `blDate` datetime(3) DEFAULT NULL,
  `warrantyMonths` int(11) DEFAULT NULL,
  `agence` varchar(191) DEFAULT NULL,
  `blNumber` varchar(191) DEFAULT NULL,
  `blDocumentUrl` varchar(191) DEFAULT NULL,
  `invoiceUrl` varchar(191) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

